fn rolling_max(s: &Vec<i8>) -> Option<i8> {
    if s.len() < 2 {
        return None;
    }

    // Initialize first_max and second_max with the minimum possible i8 value
    // We will update these while iterating over the array
    let mut first_max = i8::MIN;
    let mut second_max = i8::MIN;

    for &value in s.iter() {
        if value > first_max {
            // Found new max, push old max to second max
            second_max = first_max;
            first_max = value;
        } else if value > second_max && value < first_max {
            // Value is between first_max and second_max
            second_max = value;
        }
    }

    // If second_max was never updated (all values equal), return second_max accordingly
    // But since array length >= 2, if all equal, first_max == second_max == that value
    // In that case, second_max == first_max. As per problem,
    // second-largest means distinct from largest, so here there's no proper second largest.
    // Return None in that case.
    if second_max == i8::MIN && s.iter().all(|&v| v == first_max) {
        return None;
    }

    Some(second_max)
}